import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.CDU0sSpB.js";const _=JSON.parse('{"title":"控制面与授权","description":"Hearth 如何判断何时观察、建议、执行或停止，并把自主性限制在明确授权的范围内。","frontmatter":{"title":"控制面与授权","description":"Hearth 如何判断何时观察、建议、执行或停止，并把自主性限制在明确授权的范围内。","outline":false},"headers":[],"relativePath":"design/control.md","filePath":"design/control.md","lastUpdated":1794305977000}'),r={name:"design/control.md"};function n(l,t,p,c,i,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="控制面与授权" tabindex="-1">控制面与授权 <a class="header-anchor" href="#控制面与授权" aria-label="Permalink to &quot;控制面与授权&quot;">​</a></h1><p class="lead">控制面决定一个请求要不要处理、以什么强度处理，以及系统可以在没有人盯着的情况下走多远。它不直接执行工具，也不替用户扩大权限，而是把意图、规则、风险和注意力放在一起判断。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>系统要能从消息、邮件、日程、文件变化、网页和定时事件中发现值得处理的事情，同时避免把所有输入都变成任务。对于低价值或重复信息，系统可以观察和记录；对于明确目标，系统可以建议或创建任务；对于高风险动作，系统必须等待用户授权。</p><p>授权要具体、可见、可撤销。用户批准的是某类动作在某个范围、某段时间和某个风险等级内可以发生，而不是笼统地把全部能力交给模型。授权到期、任务结束、设备撤销或风险变化时，权限要自动收回或重新确认。</p><p>主动服务必须控制打扰。系统可以提醒、准备草稿或提前完成低风险工作，但不能因为“可能有帮助”就持续推送。每个主动动作都要有触发理由、预期收益和不打扰的边界，并且允许用户暂停、降频或只保留建议。</p><p>控制面还要做监控和止损。执行时间过长、预算异常、重复调用、状态来回跳、外部结果不确定或权限即将过期时，系统要暂停或转人工，而不是等到用户发现账单或错误。</p><h2 id="设计取舍" tabindex="-1">设计取舍 <a class="header-anchor" href="#设计取舍" aria-label="Permalink to &quot;设计取舍&quot;">​</a></h2><p>规则和模型混合判断，规则优先。明确的定时、金额、来源、关键词和风险条件用确定性规则处理；需要理解语义和上下文时再使用模型。这样既能处理开放请求，也能保证安全和成本边界不依赖模型心情。</p><table tabindex="0"><thead><tr><th>自主级别</th><th>系统可以做什么</th><th>必须发生什么</th></tr></thead><tbody><tr><td>只建议</td><td>观察、准备草稿、提出下一步</td><td>用户确认后才创建真实执行任务</td></tr><tr><td>受控执行</td><td>在已授权范围内执行低风险步骤</td><td>每个外部写入仍需预览或审批</td></tr><tr><td>授权执行</td><td>在明确任务族和范围内连续执行</td><td>高风险动作、超预算和异常必须停下</td></tr><tr><td>受监督自主</td><td>在限定时间内自主推进并处理常见异常</td><td>保留随时暂停、接管和回滚入口</td></tr></tbody></table><p>策略与执行分离。模型可以提出计划和候选动作，但不能自己修改授权规则、审批门槛和安全边界。策略变化要留下版本，旧的执行不能因为新规则出现而悄悄获得更大权限。</p><p>主动循环要有节奏。系统按事件和计划触发，不持续空转；同类提醒有冷却时间，夜间和专注时段可以静默，用户连续忽略时要降低频率。注意力预算和 Token 预算一样是硬约束，不能把“多发几条通知”当作提高完成率的手段。</p><h2 id="主动循环与提醒边界" tabindex="-1">主动循环与提醒边界 <a class="header-anchor" href="#主动循环与提醒边界" aria-label="Permalink to &quot;主动循环与提醒边界&quot;">​</a></h2><p>主动服务不再只依赖手动扫描。服务启动后先做一次扫描，随后每 5 分钟扫描；任务、审批、外部效果、来源和系统状态变化会触发 2 秒防抖扫描。扫描仍然经过 <code>enabled</code>、主动级别、每日上限、安静时段、同类冷却和去重，不因为“定时”而绕过这些限制。</p><p>长期规则由标准意图保存，心跳按意图、任务状态和到期时间生成候选；注意力治理按每日上限、安静时段、同类冷却、单目标上限和高优先级上限决定是否送达。用户忽略、稍后提醒和明确 <code>NO_REPLY</code> 都会形成反馈，系统不能用换一种说法继续追问。个人本体与 Context Pack 的边界见<a href="/hearth-os/design/personal-context.html">个人上下文与注意力</a>。</p><p>一次建议只有真正送达时才发出 <code>suggestion.event(action=&quot;delivered&quot;)</code>，并带上标题、原因和优先级。页面打开时，前端把它转换成需要你的人话提醒；页面关闭后不承诺推送。需要离开电脑接收时，飞书长连接会把审批和任务状态发到已映射会话，审批命令必须来自 <code>allowedOpenIds</code> 白名单，并且只对当前会话关联任务的一次性审批生效。</p><p>提醒渠道不能改变授权。应用内通知、桌面通知和飞书消息都只是“让人看到”的方式；批准仍然调用同一个 <code>ApprovalManager.decide</code>，拒绝仍然不产生外部副作用。没有通知通道时，系统回到应用内“需要你”；没有真实账户时，不伪造送达或回执。</p><p>控制面可以拒绝执行，也可以只完成一部分。拒绝时要说明是权限不足、风险过高、预算耗尽、信息不足还是设备不可用，并给出用户能够采取的具体动作。部分完成时要明确哪些已经做、哪些没有做，不能把半成品包装成成功。</p>',18)])])}const u=e(r,[["render",n]]);export{_ as __pageData,u as default};
